const users = [
  { id: 1, name: "Rahul", friends: [2, 3, 4, 5] },
  { id: 2, name: "Amit", friends: [1, 3, 5, 6] },
  { id: 3, name: "Vijay", friends: [1, 2, 4] }
];

const mutualFriend = (data, userId1, userId2) => {
  let output = [];

  let user1 = null;
  let user2 = null;

  // Find both users
  for (let i = 0; i < data.length; i++) {
    if (data[i].id === userId1) {
      user1 = data[i];
    }

    if (data[i].id === userId2) {
      user2 = data[i];
    }
  }

  if (!user1 || !user2) {
    return output;
  }

  // Find common friends
  for (let i = 0; i < user1.friends.length; i++) {
    for (let j = 0; j < user2.friends.length; j++) {
      if (user1.friends[i] === user2.friends[j]) {
        output[output.length] = user1.friends[i];
        break;
      }
    }
  }

  return output;
};

console.log('-->>', mutualFriend(users, 1, 2));
